/**
 * OG card logo asset — embedded as a data URI so the /og ImageResponse can
 * render the YehThatRocks logo without a filesystem read or a network fetch
 * (the /og route runs on the edge runtime).
 *
 * Source: apps/web/public/assets/images/yeh_main_logo.png (1356x448).
 * Rendered in the home card at 678x224 (exact 0.5x, no aspect distortion).
 *
 * Regenerate (Python 3, stdlib only):
 *   python3 -c "import base64; print('data:image/png;base64,' + \
 *     base64.b64encode(open('apps/web/public/assets/images/yeh_main_logo.png','rb').read()).decode())"
 */
export const OG_LOGO_DATA_URI = "data:image/png;base64,";

/** Intrinsic source dimensions (not the render size). */
export const OG_LOGO_WIDTH = 1356;
export const OG_LOGO_HEIGHT = 448;
